 static final class Row {private final int[] colors,tags;Row(int[] c,int[] t){colors=c;tags=t;}int[] colors(){return colors.clone();}int[] tags(){return tags.clone();}}
 private static final int[][][] SIZES={{{8,8},{16,16},{32,32},{64,64}},{{16,8},{32,8},{32,16},{64,32}},{{8,16},{8,32},{16,32},{32,64}}};
