 static int effect(int color,int effect,int amount){int result=0xff000000;for(int k=0;k<3;k++){int mask=255<<(k*8),c=color&mask;if(effect==2)c+=((mask-c)*amount)/16;else if(effect==3)c-=(c*amount)/16;result|=c&mask;}return result;}
